Here is the root cause:
The bug is caused by a deadlock situation where the output poll worker calls `pm_runtime_get_sync()` in the `->detect` hooks while the `->runtime_suspend` hook is waiting for the output poll worker to finish. This creates a circular dependency, leading to both processes being blocked indefinitely.

Here is the patch:

 static enum drm_connector_status
 radeon_lvds_detect(struct drm_connector *connector, bool force)
 {
 	struct drm_device *dev = connector->dev;
 	struct radeon_device *rdev = dev->dev_private;
 	struct radeon_connector *radeon_connector = to_radeon_connector(connector);
 	struct drm_encoder *encoder = radeon_best_single_encoder(connector);
 	enum drm_connector_status ret = connector_status_disconnected;
 	int r;

-	r = pm_runtime_get_sync(connector->dev->dev);
-	if (r < 0)
-		return connector_status_disconnected;
+	if (!drm_kms_helper_is_poll_worker()) {
+		r = pm_runtime_get_sync(connector->dev->dev);
+		if (r < 0)
+			return connector_status_disconnected;
+	}

 	if (encoder) {
 		struct radeon_encoder *radeon_encoder = to_radeon_encoder(encoder);
 		struct drm_display_mode *native_mode = &radeon_encoder->native_mode;

 		/* check if panel is valid */
 		if (native_mode->hdisplay >= 320 && native_mode->vdisplay >= 240)
 			ret = connector_status_connected;
 		/* don't fetch the edid from the vbios if ddc fails and runpm is
 		 * enabled so we report disconnected.
 		 */
 		if ((rdev->flags & RADEON_IS_PX) && (radeon_runtime_pm != 0))
 			ret = connector_status_disconnected;
 	}

 	/* check for edid as well */
